/**
 * Unit tests for StrBuilder.appendFixedWidthPadLeft
 */
public class StrBuilder_appendFixedWidthPadLeft_TriageGen1Test {







    @Test
    public void testAppendFixedWidthPadLeft_NoPaddingNeeded() {
        StrBuilder sb = new StrBuilder();
        // obj="abcdef" (len 6), width=3 -> "def" (based on strLen % width logic in code)
        // Note: The implementation uses str.getChars(strLen % width, strLen, buffer, size)
        // If strLen=6, width=3, strLen % width = 0. It takes from index 0 to 6.
        // Wait, the code says: if (strLen >= width) { str.getChars(strLen % width, strLen, buffer, size); }
        // If strLen=6, width=3, strLen % width = 0. It copies 6 chars into size. 
        // However, size += width is called at the end.
        // Let's trace: size=0, width=3, strLen=6. strLen >= width is true.
        // str.getChars(0, 6, buffer, 0). size becomes 0 + 3 = 3.
        // This logic in the provided source code seems to actually truncate or behave oddly if strLen > width.
        // We test the behavior as written in the provided snippet.
        sb.appendFixedWidthPadLeft("abcdef", 3, '0');
        // strLen=6, width=3. strLen % width = 0. str.getChars(0, 6, buffer, 0).
        // size += 3. Resulting length is 3.
        assertEquals(3, sb.length());
    }












}

